      "experience.title": "Mi Experiencia",
      "experience.description": "He trabajado con marcas de bienes raíces, antigüedades, mayoristas y comercio electrónico; combinando diseño, marketing y análisis para generar crecimiento y resultados medibles.",
      "experience.job1.title": "Diseñador Digital",
