      "skills.title": "Mis Habilidades",
      "skills.description": "Con experiencia en Adobe After Effects, Premiere, Photoshop, Illustrator y Express, además de herramientas como CapCut, Canva, Notion, Trello, Asana, WordPress y Google & Meta Ads. Tengo todo lo necesario para crear y escalar marcas digitales que vendan.",
      "skills.notion": "Notion",
      "skills.frontend": "Front-End",
      "skills.adobesuite": "Adobe Suite",
