      "clienttodxspodemosser.projectInfo.title": "Información del Proyecto",
      "clienttodxspodemosser.projectInfo.clients": "Clientes",
      "clienttodxspodemosser.projectInfo.clientName": "Mima Cortez",
      "clienttodxspodemosser.projectInfo.date": "Fecha",
      "clienttodxspodemosser.projectInfo.dateValue": "1 de agosto de 2020",
      "clienttodxspodemosser.projectInfo.category": "Categoría",
